def set_cell_shading(cell, fill):
    tcPr=cell._tc.get_or_add_tcPr(); shd=OxmlElement('w:shd'); shd.set(qn('w:fill'),fill); tcPr.append(shd)
def set_cell_margins(cell, top=100, start=130, bottom=100, end=130):
    tc=cell._tc; tcPr=tc.get_or_add_tcPr(); tcMar=tcPr.first_child_found_in('w:tcMar')
    if tcMar is None: tcMar=OxmlElement('w:tcMar'); tcPr.append(tcMar)
    for m,v in [('top',top),('start',start),('bottom',bottom),('end',end)]:
        el=tcMar.find(qn('w:'+m))
        if el is None: el=OxmlElement('w:'+m);tcMar.append(el)
        el.set(qn('w:w'),str(v));el.set(qn('w:type'),'dxa')
def set_repeat_table_header(row):
    trPr=row._tr.get_or_add_trPr(); tblHeader=OxmlElement('w:tblHeader'); tblHeader.set(qn('w:val'),'true');trPr.append(tblHeader)
def add_field(paragraph, instruction):
    run=paragraph.add_run(); begin=OxmlElement('w:fldChar');begin.set(qn('w:fldCharType'),'begin')
    instr=OxmlElement('w:instrText');instr.set(qn('xml:space'),'preserve');instr.text=instruction
    sep=OxmlElement('w:fldChar');sep.set(qn('w:fldCharType'),'separate'); txt=OxmlElement('w:t');txt.text='1';end=OxmlElement('w:fldChar');end.set(qn('w:fldCharType'),'end')
    run._r.extend([begin,instr,sep,txt,end])
def add_table(doc, headers, rows, widths=None):
    t=doc.add_table(rows=1, cols=len(headers));t.alignment=WD_TABLE_ALIGNMENT.CENTER;t.style='Table Grid'
    set_repeat_table_header(t.rows[0])
    for i,h in enumerate(headers):
        c=t.rows[0].cells[i];c.text=h;set_cell_shading(c,'243B53');set_cell_margins(c);c.vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.CENTER
        for r in c.paragraphs[0].runs:r.bold=True;r.font.color.rgb=RGBColor(255,255,255);r.font.size=Pt(9)
    for ri,row in enumerate(rows):
        cells=t.add_row().cells
        for i,val in enumerate(row):
            cells[i].text=str(val);set_cell_margins(cells[i]);cells[i].vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.CENTER
            if ri%2==1:set_cell_shading(cells[i],'F1F5F9')
            for p in cells[i].paragraphs:
                p.paragraph_format.space_after=Pt(2)
                for r in p.runs:r.font.size=Pt(8.8)
    return t
def add_body(doc,text):
    p=doc.add_paragraph(text,style='Body Text');p.paragraph_format.widow_control=True;return p
def add_bullet(doc,text):
    p=doc.add_paragraph(style='List Bullet');p.add_run(text);return p
def add_page(doc, chapter_no, chapter_title, page_title, p1, p2, bullets=None, diagram=None, table=None, image=None):
    doc.add_page_break()
    h=doc.add_paragraph(f'{chapter_no}  {chapter_title.upper()}',style='Heading 1');h.paragraph_format.keep_with_next=True
    doc.add_paragraph(page_title,style='Heading 2')
    add_body(doc,p1);add_body(doc,p2)
    if diagram:
        doc.add_picture(str(TMP/f'{diagram}.png'),width=Inches(5.9));doc.paragraphs[-1].alignment=WD_ALIGN_PARAGRAPH.CENTER
        cp=doc.add_paragraph(f'Figure {chapter_no}.{pno}  {dict(arch="HAKI logical architecture",flow="Commit-bound validation sequence",state="Illustrative submission state path",trust="Trust boundaries",entities="Core data relationships")[diagram]}',style='Caption');cp.alignment=WD_ALIGN_PARAGRAPH.CENTER
    if table:
        headers,rows=table;add_table(doc,headers,rows)
    if bullets:
        for b in bullets:add_bullet(doc,b)

