normal=styles['Normal'];normal.font.name='Cambria';normal.font.size=Pt(11.3);normal.font.color.rgb=RGBColor(24,32,48);normal.paragraph_format.line_spacing=1.26;normal.paragraph_format.space_after=Pt(7)
